export const MONSOON_DATA={sw:{id:"sw",title:"Southwest Monsoon (Summer / Advancing)",months:"June – September",rainfallShare:"75% – 90% of India's Total Annual Rainfall",direction:"South-West to North-East",origin:"Indian Ocean & Equatorial Waters",summary:"Created by intense differential heating over the Thar Desert and Indo-Gangetic Plains. Moisture-laden ocean winds sweep from the southwest, splitting into the Arabian Sea and Bay of Bengal branches.",mechanism:"During summer (May–June), intense solar radiation heats the northern Indian landmass far more rapidly than the surrounding ocean, establishing a powerful thermal low-pressure trough (ITCZ). Southeasterly trade winds crossing the equator deflect to the right due to the Coriolis Force, becoming moisture-rich Southwesterly winds.",branches:[{name:"Arabian Sea Branch",desc:"Strikes the Western Ghats perpendicularly, causing heavy orographic precipitation along the Konkan and Malabar coasts (over 250 cm rain), before crossing the Deccan Plateau."},{name:"Bay of Bengal Branch",desc:"Moves across the Bay of Bengal, hitting the Arakan Hills and Meghalaya Plateau (Mawsynram/Cherrapunji), then turns westward along the Himalayas across the Gangetic Plains."}],phases:[{step:1,title:"Phase 1: Differential Heating & ITCZ Northward Shift",period:"May – Early June",desc:"Land surface temperatures over North India exceed 45°C. The Intertropical Convergence Zone (ITCZ) shifts northward over the Gangetic Plain, generating an intense low-pressure cell that acts as a atmospheric vacuum."},{step:2,title:"Phase 2: Monsoon Onset over Kerala",period:"June 1 – June 5",desc:"The monsoon officially arrives over the southern tip of Kerala ('Monsoon Burst'). Strong southwesterly winds (30–40 knots) bring thunderous rains and a sudden drop in regional temperatures."},{step:3,title:"Phase 3: Dual Branch Advance Across India",period:"June 10 – July 15",desc:"The Arabian Sea branch advances up the west coast and central India, while the Bay of Bengal branch sweeps into the North-East and Ganga basin, uniting over Punjab and Rajasthan by mid-July."},{step:4,title:"Phase 4: Peak Rainfall & Kharif Agriculture",period:"July – August",desc:"Widespread monsoon depressions bring critical rainfall to India's agricultural heartland, filling major river reservoirs and driving the sowing of Kharif crops (rice, cotton, sugarcane, pulses)."}],windPaths:[{id:"sw-path-arabian",label:"Arabian Sea Branch Path",pathD:"M 150 480 Q 200 400 240 320 T 320 200"},{id:"sw-path-bay",label:"Bay of Bengal Branch Path",pathD:"M 320 480 Q 420 380 440 260 T 380 140"}]},ne:{id:"ne",title:"Northeast Monsoon (Winter / Retreating)",months:"October – December",rainfallShare:"48% of Tamil Nadu's Annual Rainfall",direction:"North-East to South-West",origin:"Eurasian Landmass & Bay of Bengal",summary:"Triggered as the Indian landmass cools rapidly in autumn, establishing high pressure over Northern India. Dry continental winds reverse direction, pick up moisture over the Bay of Bengal, and deposit rain along the Coromandel Coast.",mechanism:"With the southward migration of the sun toward the Tropic of Capricorn in autumn, the ITCZ retreats southward. High atmospheric pressure forms over Tibet and Northwest India. Winds reverse direction, blowing from the cool northeast landmass toward the warm low-pressure ocean waters.",branches:[{name:"Continental Dry Branch",desc:"Blowing over the dry landmass of Northern and Central India, bringing clear skies and cool temperatures across North India."},{name:"Coromandel Coastal Branch",desc:"As winds cross the Bay of Bengal, they absorb significant ocean moisture, striking the Coromandel Coast (Tamil Nadu, Puducherry, Coastal Andhra Pradesh)."}],phases:[{step:1,title:"Phase 1: ITCZ Southward Retreat",period:"September 15 – October 1",desc:"Solar radiation shifts southward. The low-pressure trough weakens over Northern India and retreats from Rajasthan and Punjab."},{step:2,title:"Phase 2: Wind Reversal & High Pressure Build-up",period:"October 1 – October 15",desc:"A high-pressure cell forms over the cold Eurasian and Tibetan landmass. Surface winds reverse direction from southwesterly to northeasterly."},{step:3,title:"Phase 3: Bay of Bengal Moisture Absorption",period:"October 15 – November 15",desc:"Northeasterly winds sweep over the warm Bay of Bengal, picking up abundant water vapor before reaching southern India."},{step:4,title:"Phase 4: Coromandel Coast Rainfall & Rabi Crops",period:"November – December",desc:"Heavy winter precipitation falls on Tamil Nadu, Puducherry, and Rayalaseema, recharging groundwater and supporting Rabi crop cultivation in Southern India."}],windPaths:[{id:"ne-path-continental",label:"Continental Retreat Path",pathD:"M 380 140 Q 340 240 300 320"},{id:"ne-path-coastal",label:"Bay of Bengal Coastal Path",pathD:"M 460 220 Q 420 340 320 440"}]}};export function getMonsoonModeData(e="sw",t=MONSOON_DATA){return t[(e||"sw").toLowerCase().trim()]||t.sw}export function getPhaseDetails(e="sw",t=1,n=MONSOON_DATA){const s=getMonsoonModeData(e,n);if(!s||!s.phases)return null;const a=Math.max(0,Math.min(s.phases.length-1,t-1));return s.phases[a]}export function calculateWindPathDashOffset(e=0,t=500){const n=t*(1-Math.max(0,Math.min(100,e))/100);return Math.round(n)}export function validateScientificData(e=MONSOON_DATA){const t=[];return["sw","ne"].forEach(n=>{if(!e[n])return void t.push(`Missing monsoon mode: ${n}`);const s=e[n];s.title&&s.mechanism&&s.phases&&Array.isArray(s.phases)?s.phases.length<4&&t.push(`Mode ${n} must contain at least 4 scientific phases`):t.push(`Incomplete structure in mode ${n}`)}),{isValid:0===t.length,errors:t}}class MonsoonExplainerApp{constructor(){this.currentMode="sw",this.currentStep=1,this.initElements(),this.bindEvents(),this.renderActiveMode()}initElements(){this.btnModeSw=document.getElementById("btn-mode-sw"),this.btnModeNe=document.getElementById("btn-mode-ne"),this.heroTitleEl=document.getElementById("explainer-mode-title"),this.heroSubtitleEl=document.getElementById("explainer-mode-sub"),this.mechanismTextEl=document.getElementById("mechanism-text"),this.branchesListEl=document.getElementById("branches-list"),this.phasesContainerEl=document.getElementById("phases-container"),this.svgWindGroupSw=document.getElementById("svg-wind-sw"),this.svgWindGroupNe=document.getElementById("svg-wind-ne"),this.stepPrevBtn=document.getElementById("step-prev"),this.stepNextBtn=document.getElementById("step-next"),this.stepIndicatorEl=document.getElementById("step-indicator")}bindEvents(){this.btnModeSw&&this.btnModeSw.addEventListener("click",()=>this.switchMode("sw")),this.btnModeNe&&this.btnModeNe.addEventListener("click",()=>this.switchMode("ne")),this.stepPrevBtn&&this.stepPrevBtn.addEventListener("click",()=>this.changeStep(-1)),this.stepNextBtn&&this.stepNextBtn.addEventListener("click",()=>this.changeStep(1));const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{document.body.classList.toggle("light-theme")})}switchMode(e){this.currentMode=e,this.currentStep=1,this.btnModeSw&&this.btnModeNe&&(this.btnModeSw.classList.toggle("active","sw"===e),this.btnModeNe.classList.toggle("active","ne"===e),this.btnModeSw.setAttribute("aria-pressed","sw"===e),this.btnModeNe.setAttribute("aria-pressed","ne"===e)),this.renderActiveMode()}changeStep(e){const t=getMonsoonModeData(this.currentMode,MONSOON_DATA).phases.length;this.currentStep=Math.max(1,Math.min(t,this.currentStep+e)),this.updateStepUI()}renderActiveMode(){const e=getMonsoonModeData(this.currentMode,MONSOON_DATA);this.heroTitleEl&&(this.heroTitleEl.textContent=e.title),this.heroSubtitleEl&&(this.heroSubtitleEl.textContent=`${e.months} • ${e.rainfallShare}`),this.mechanismTextEl&&(this.mechanismTextEl.textContent=e.mechanism),this.branchesListEl&&(this.branchesListEl.innerHTML=e.branches.map(e=>`\n          <div class="branch-card">\n            <h4>${e.name}</h4>\n            <p>${e.desc}</p>\n          </div>\n        `).join("")),this.svgWindGroupSw&&this.svgWindGroupNe&&("sw"===this.currentMode?(this.svgWindGroupSw.style.display="block",this.svgWindGroupNe.style.display="none"):(this.svgWindGroupSw.style.display="none",this.svgWindGroupNe.style.display="block")),this.renderPhases(e),this.updateStepUI()}renderPhases(e){this.phasesContainerEl&&(this.phasesContainerEl.innerHTML="",e.phases.forEach(e=>{const t=document.createElement("div");t.className="phase-card "+(e.step===this.currentStep?"active":""),t.dataset.step=e.step,t.innerHTML=`\n        <div class="phase-header">\n          <span class="phase-step-badge">Step ${e.step}</span>\n          <span class="phase-period">${e.period}</span>\n        </div>\n        <h3 class="phase-title">${e.title}</h3>\n        <p class="phase-desc">${e.desc}</p>\n      `,t.addEventListener("click",()=>{this.currentStep=e.step,this.updateStepUI()}),this.phasesContainerEl.appendChild(t)}))}updateStepUI(){const e=getMonsoonModeData(this.currentMode,MONSOON_DATA).phases.length;this.stepIndicatorEl&&(this.stepIndicatorEl.textContent=`Phase ${this.currentStep} of ${e}`),this.stepPrevBtn&&(this.stepPrevBtn.disabled=1===this.currentStep),this.stepNextBtn&&(this.stepNextBtn.disabled=this.currentStep===e);(this.phasesContainerEl?this.phasesContainerEl.querySelectorAll(".phase-card"):[]).forEach(e=>{const t=parseInt(e.dataset.step,10);e.classList.toggle("active",t===this.currentStep)});const t=this.currentStep/e*100;("sw"===this.currentMode?this.svgWindGroupSw:this.svgWindGroupNe).querySelectorAll(".animated-wind-path").forEach(e=>{const n=calculateWindPathDashOffset(t,500);e.style.strokeDashoffset=`${n}px`})}}"undefined"!=typeof window&&"undefined"!=typeof document&&(window.MonsoonExplainer={MONSOON_DATA:MONSOON_DATA,getMonsoonModeData:getMonsoonModeData,getPhaseDetails:getPhaseDetails,calculateWindPathDashOffset:calculateWindPathDashOffset,validateScientificData:validateScientificData,MonsoonExplainerApp:MonsoonExplainerApp},document.addEventListener("DOMContentLoaded",()=>{document.getElementById("explainer-mode-title")&&new MonsoonExplainerApp}));